        if isinstance(item, list):
            out.extend(flatten(item))
        else:
            out.append(item)
    return out

alt:
def flatten(items):
    stack = list(items)[::-1]
    out = []
    while stack:
        item = stack.pop()
        if isinstance(item, list):
            stack.extend(item[::-1])
        else:
            out.append(item)
    return out
